export function getAllPosts(lang = 'de') {
  const posts = BLOG[lang] || BLOG.de;
  return Object.entries(posts).map(([slug, data]) => ({
    slug,
    ...data
  })).sort((a, b) => new Date(b.published) - new Date(a.published));
}

export function getPost(slug, lang = 'de') {
  const posts = BLOG[lang] || BLOG.de;
  return posts[slug] ? { slug, ...posts[slug] } : null;
}

export function getMeta(slug, lang = 'de') {
  const posts = BLOG[lang] || BLOG.de;
  return posts[slug]?.meta || null;
}

export default BLOG;
